def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def safe_pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return [value[0], value[1]]
        return [default[0], default[1]]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def bounds(obs):
        w = obs.get("grid_width")
        h = obs.get("grid_height")
        if not isinstance(w, int) or w <= 0:
            w = 1
        if not isinstance(h, int) or h <= 0:
            h = 1
        return w, h

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position", (0, 0)))
    ox, oy = safe_pos(observation.get("opponent_position", (sx, sy)))
    self_pos = [sx, sy]
    opp_pos = [ox, oy]
    w, h = bounds(observation)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [[0, 0], [0, h - 1], [w - 1, 0], [w - 1, h - 1]]
        target = max(corners, key=lambda p: manhattan(p, opp_pos))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_score = None
        for item in targets:
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                p = [item[0], item[1]]
                score = manhattan(p, self_pos)
                if best is None or score < best_score:
                    best = p
                    best_score = score
        if best is not None:
            return step_toward(self_pos, best)
        center = [(w - 1) // 2, (h - 1) // 2]
        if self_pos == center:
            if manhattan(self_pos, opp_pos) > 0:
                return step_toward(self_pos, opp_pos)
            return [0, 0]
        return step_toward(self_pos, center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = None
    for item in resources:
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            p = [item[0], item[1]]
            score = manhattan(p, self_pos)
            if best is None or score < best_score:
                best = p
                best_score = score

    if best is not None:
        return step_toward(self_pos, best)

    if manhattan(self_pos, opp_pos) > 1:
        return step_toward(self_pos, opp_pos)

    if sx + sy <= (w - 1 - sx) + (h - 1 - sy):
        return [1 if sx < w - 1 else 0, 0]
    return [0, 1 if sy < h - 1 else 0]

